'use strict';
(() => {
 const $ = (s) => document.querySelector(s);
 const icons = {welcome:'grid',motion:'play',comfort:'sliders',activity:'layers',note:'note'};
 const defaults = [
  {id:'overview',type:'welcome',name:'Workspace overview',x:24,y:20,z:0,width:772,height:128,opacity:96,radius:16,visible:true,locked:false},
  {id:'motion',type:'motion',name:'Motion control',x:24,y:164,z:100,width:440,height:250,opacity:96,radius:16,visible:true,locked:false},
  {id:'comfort',type:'comfort',name:'Comfort settings',x:480,y:164,z:50,width:316,height:250,opacity:96,radius:16,visible:true,locked:false},
  {id:'activity',type:'activity',name:'Motion preview',x:24,y:430,z:30,width:440,height:112,opacity:96,radius:16,visible:true,locked:false},
  {id:'note',type:'note',name:'Design notes',x:480,y:430,z:75,width:316,height:112,opacity:96,radius:16,visible:true,locked:false}
 ];
 const systemMotion = matchMedia('(prefers-reduced-motion: reduce)');
 let state = {layers:structuredClone(defaults),selected:'motion',mode:'2d',zoom:1,spread:75,orbit:-18,tilt:24,playing:false,reduced:systemMotion.matches,grid:true,contrast:false};
 let fitted=1, toastTimer, dragging=null;
 const selected=()=>state.layers.find(l=>l.id===state.selected);
 const icon=(name)=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
 const escape=(value)=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
 function contents(l){
  const head=`<div class="layer-header" data-drag="${l.id}"><span>${escape(l.name)}</span>${icon(icons[l.type])}</div>`;
  if(l.type==='welcome')return `<div class="layer-header" data-drag="${l.id}" aria-hidden="true"></div><div class="welcome-copy"><p class="welcome-kicker">YOUR PERSONAL WORKSPACE</p><h2 class="welcome-title">Good work. <em>Less motion.</em></h2><p class="welcome-subtitle">A little more focus. A space that feels like yours.</p></div><div class="welcome-clock"><strong>01 / 05</strong><span>DESIGN STUDIO</span></div>`;
  if(l.type==='motion')return `${head}<div class="motion-display"><div class="loop-orbit ribbon-preview" aria-hidden="true"><img class="motion-ribbon" src="/assets/starter-motion.svg" alt="" width="1024" height="1536" draggable="false"><div class="orbit-inner">${icon('pause')}</div></div><div class="motion-copy"><h3>Let it flow.<br><em>Or let it stop.</em></h3><p>Give every loop a pause.<br>Keep your focus in control.</p></div></div><div class="card-footer"><span>6 SECOND LOOP</span><button class="inline-play" data-action="motion">${icon(state.playing?'pause':'play')}<span>${state.playing?'Pause':'Play'} loop</span></button></div>`;
  if(l.type==='comfort')return `${head}<div class="comfort-row"><span>Keyboard editing</span><span class="check-circle">${icon('check')}</span></div><div class="comfort-row"><span>2D always available</span><span class="check-circle">${icon('check')}</span></div><div class="comfort-row"><span>Motion preference</span><span class="comfort-motion-value">${state.reduced?'Reduced':'Standard'}</span></div><div class="comfort-foot">${icon('sliders')}<span>Adjust comfort in the inspector</span></div>`;
  if(l.type==='activity')return `${head}<div class="activity-main"><div class="activity-bars" aria-hidden="true">${Array.from({length:25},(_,i)=>`<i style="--bar:${8+((i*17+7)%25)}px;--delay:${i*-.13}s"></i>`).join('')}</div><p class="activity-status">${state.playing?'Playing':'Paused'}</p></div>`;
  return `${head}<p>${l.id==='note'?'Design flat. Explore depth.<br>Keep every interaction intentional.':'A new place for your next idea.'}</p>`;
 }
 function renderLayers(){
  $('#layer-list').innerHTML=state.layers.map((l,i)=>`<div class="layer-row${l.id===state.selected?' selected':''}${!l.visible?' is-hidden':''}" data-row="${l.id}"><button class="layer-select" data-select="${l.id}" aria-pressed="${l.id===state.selected}">${icon(icons[l.type])}<span class="layer-title">${escape(l.name)}</span></button><button class="visibility icon-button" data-visible="${l.id}" aria-label="${l.visible?'Hide':'Show'} ${escape(l.name)}" aria-pressed="${l.visible}">${icon('eye')}</button></div>`).join('');
  $('#scene-layers').innerHTML=state.layers.map((l,i)=>`<article class="layer ${l.type==='welcome'?'welcome':l.type==='comfort'?'a11y':l.type==='activity'?'activity':l.type==='note'?'note':'motion'}-layer" data-layer="${l.id}" aria-label="${escape(l.name)}" tabindex="0"><span class="layer-label-3d" aria-hidden="true">${String(i+1).padStart(2,'0')} / ${escape(l.name)} <span class="z-tag"></span></span><div class="layer-content">${contents(l)}</div>${'<i class="selection-handle" aria-hidden="true"></i>'.repeat(4)}</article>`).join('');
  applyGeometry();syncInspector();syncMotion();
 }
 function applyGeometry(){
  for(const l of state.layers){const el=$(`[data-layer="${l.id}"]`);if(!el)continue;Object.assign(el.style,{left:l.x+'px',top:l.y+'px',width:l.width+'px',height:l.height+'px'});el.style.setProperty('--z',l.z);el.style.setProperty('--layer-opacity',l.opacity/100);el.style.setProperty('--radius',l.radius+'px');el.hidden=!l.visible;el.classList.toggle('selected',l.id===state.selected);el.classList.toggle('is-locked',l.locked);el.querySelector('.z-tag').textContent=`· Z ${l.z}`;const row=$(`[data-row="${l.id}"]`);row?.classList.toggle('selected',l.id===state.selected);row?.querySelector('[data-select]')?.setAttribute('aria-pressed',String(l.id===state.selected));}
  $('.layer-total').textContent=String(state.layers.length).padStart(2,'0');$('#layer-count').textContent=`${state.layers.filter(l=>l.visible).length} of ${state.layers.length} layers visible`;fit();
 }
 function syncInspector(){const l=selected();if(!l)return;$('#selected-heading').textContent=l.name;$('#selected-icon use').setAttribute('href','#i-'+icons[l.type]);$('#selected-type').textContent=l.locked?'LOCKED LAYER':'SELECTED LAYER';$('#layer-name').value=l.name;for(const key of ['x','y','z','width','height']){$('#prop-'+key).value=l[key];$('#prop-'+key).disabled=l.locked;}$('#opacity').value=l.opacity;$('#opacity-value').value=l.opacity+'%';$('#radius').value=l.radius;$('#radius-value').value=l.radius+' px';$('#lock-layer').setAttribute('aria-pressed',String(l.locked));$('#lock-layer').setAttribute('aria-label',l.locked?'Unlock selected layer':'Lock selected layer');}
 function selectLayer(id,announce=false){if(!state.layers.some(l=>l.id===id))throw new Error('Unknown layer');state.selected=id;applyGeometry();syncInspector();if(announce)toast('Selected '+selected().name);}
 function fit(){const visible=state.layers.filter(l=>l.visible);const w=Math.max(820,...visible.map(l=>l.x+l.width+24));const h=Math.max(560,...visible.map(l=>l.y+l.height+18));const viewport=$('#viewport');const availableW=Math.max(260,viewport.clientWidth-95);const availableH=Math.max(280,viewport.clientHeight-155);fitted=Math.min(availableW/w,availableH/h,1.12)*state.zoom;const scene=$('#scene');scene.style.width=w+'px';scene.style.height=h+'px';scene.style.setProperty('--fit',fitted);scene.style.setProperty('--spread',state.spread/75);scene.style.setProperty('--orbit',state.orbit+'deg');scene.style.setProperty('--tilt',state.tilt+'deg');$('#scene-dimensions').textContent=`${w} × ${h}`;$('#zoom-value').value=Math.round(state.zoom*100)+'%';}
 function setMode(mode){if(!['2d','3d'].includes(mode))throw new Error('Mode must be 2d or 3d');state.mode=mode;$('#scene').classList.toggle('is-3d',mode==='3d');$('#viewport').classList.toggle('spatial',mode==='3d');$('#view-2d').setAttribute('aria-pressed',String(mode==='2d'));$('#view-3d').setAttribute('aria-pressed',String(mode==='3d'));$('#dimension-toggle').innerHTML=icon(mode==='3d'?'square':'cube')+`<span>${mode==='3d'?'Back to 2D':'Enter 3D'}</span>`;$('#view-caption').textContent=mode==='3d'?'Spatial canvas':'Flat canvas';$('#dimension-status').textContent=mode==='3d'?'3D workspace':'2D workspace';$('#canvas-hint').textContent=mode==='3d'?'Same layers, new perspective · adjust spread, orbit and tilt':'Select a layer to edit · drag its header to move';$('#spatial-toolbar').hidden=mode!=='3d';requestAnimationFrame(fit);toast(mode==='3d'?'Your layers, in another dimension.':'Back in 2D. Your edits are preserved.');return {mode:state.mode,layers:state.layers.length};}
 function syncMotion(){document.body.classList.toggle('playing',state.playing&&!state.reduced);document.body.classList.toggle('reduced',state.reduced);$('#motion-toggle').setAttribute('aria-pressed',String(state.playing));$('#motion-toggle').innerHTML=icon(state.playing?'pause':'play')+`<span>${state.playing?'Pause motion':'Play motion'}</span>`;$('#motion-toggle').disabled=state.reduced;$('#motion-state').textContent=state.reduced?'Reduced motion':state.playing?'Motion playing':'Motion paused';$('#reduce-motion').checked=state.reduced;$('#reduce-toggle').setAttribute('aria-pressed',String(state.reduced));document.querySelectorAll('[data-action="motion"]').forEach(b=>{b.disabled=state.reduced;b.innerHTML=icon(state.playing?'pause':'play')+`<span>${state.playing?'Pause':'Play'} loop</span>`;});document.querySelectorAll('.activity-status').forEach(el=>el.textContent=state.playing?'Playing':'Paused');document.querySelectorAll('.comfort-motion-value').forEach(el=>el.textContent=state.reduced?'Reduced':'Standard');document.querySelectorAll('.orbit-inner').forEach(el=>el.innerHTML=icon(state.playing?'play':'pause'));}
 function toggleMotion(){if(state.reduced){toast('Reduced motion is on. Disable it to play the loop.');return;}state.playing=!state.playing;syncMotion();}
 function setReduced(value){state.reduced=Boolean(value)||systemMotion.matches;if(state.reduced)state.playing=false;syncMotion();if(systemMotion.matches&&!value)toast('Your system motion preference is respected.');}
 function updateLayer(updates){const l=selected();if(!l)throw new Error('No selected layer');const limits={x:[0,1200],y:[0,900],z:[0,300],width:[220,1000],height:[90,600],opacity:[45,100],radius:[0,32]};for(const [key,value] of Object.entries(updates)){if(key==='name'){const name=String(value).trim().slice(0,60);if(!name)throw new Error('A layer name is required');l.name=name;}else if(key in limits){if(l.locked&&['x','y','z','width','height'].includes(key))throw new Error('Unlock the layer to change its position or size');const n=Number(value);if(!Number.isFinite(n))throw new Error('Use a valid number');const [min,max]=limits[key];l[key]=Math.min(max,Math.max(min,n));}else throw new Error('Unknown property');}applyGeometry();syncInspector();return structuredClone(l);}
 $('#layer-list').addEventListener('click',e=>{const select=e.target.closest('[data-select]');const visibility=e.target.closest('[data-visible]');if(select)selectLayer(select.dataset.select);if(visibility){const l=state.layers.find(l=>l.id===visibility.dataset.visible);l.visible=!l.visible;const id=l.id;renderLayers();$(`[data-visible="${id}"]`).focus();toast(`${l.name} ${l.visible?'shown':'hidden'}`);}});
 $('#scene-layers').addEventListener('click',e=>{if(e.target.closest('[data-action="motion"]')){toggleMotion();return;}const layer=e.target.closest('[data-layer]');if(layer)selectLayer(layer.dataset.layer);});
 $('#scene-layers').addEventListener('keydown',e=>{if(e.target!==e.target.closest('[data-layer]'))return;const el=e.target.closest('[data-layer]');if(!el)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();selectLayer(el.dataset.layer,true);}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();selectLayer(el.dataset.layer);const l=selected();if(l.locked)return;const step=e.shiftKey?20:4;if(e.key==='ArrowLeft')updateLayer({x:l.x-step});if(e.key==='ArrowRight')updateLayer({x:l.x+step});if(e.key==='ArrowUp')updateLayer({y:l.y-step});if(e.key==='ArrowDown')updateLayer({y:l.y+step});}});
 $('#scene-layers').addEventListener('pointerdown',e=>{const header=e.target.closest('[data-drag]');if(!header||e.button!==0||state.mode!=='2d')return;const l=state.layers.find(l=>l.id===header.dataset.drag);selectLayer(l.id);if(l.locked)return;dragging={id:l.id,clientX:e.clientX,clientY:e.clientY,x:l.x,y:l.y,scale:fitted,pointer:e.pointerId};header.setPointerCapture(e.pointerId);document.body.classList.add('is-dragging');});
 $('#scene-layers').addEventListener('pointermove',e=>{if(!dragging||e.pointerId!==dragging.pointer)return;const l=selected();l.x=Math.max(0,Math.min(1200,Math.round((dragging.x+(e.clientX-dragging.clientX)/dragging.scale)/4)*4));l.y=Math.max(0,Math.min(900,Math.round((dragging.y+(e.clientY-dragging.clientY)/dragging.scale)/4)*4));const el=$(`[data-layer="${l.id}"]`);el.style.left=l.x+'px';el.style.top=l.y+'px';$('#prop-x').value=l.x;$('#prop-y').value=l.y;});
 const endDrag=()=>{if(!dragging)return;dragging=null;document.body.classList.remove('is-dragging');applyGeometry();};$('#scene-layers').addEventListener('pointerup',endDrag);$('#scene-layers').addEventListener('pointercancel',endDrag);
 $('#layer-name').addEventListener('change',e=>{try{updateLayer({name:e.target.value});renderLayers();$('#layer-name').focus();}catch(error){toast(error.message);syncInspector();}});
 for(const key of ['x','y','z','width','height'])$('#prop-'+key).addEventListener('change',e=>{try{updateLayer({[key]:e.target.value});}catch(error){toast(error.message);syncInspector();}});
 for(const key of ['opacity','radius'])$('#'+key).addEventListener('input',e=>updateLayer({[key]:e.target.value}));
 $('#lock-layer').addEventListener('click',()=>{selected().locked=!selected().locked;applyGeometry();syncInspector();toast(selected().locked?'Layer position and size locked.':'Layer unlocked.');});
 $('#view-2d').addEventListener('click',()=>setMode('2d'));$('#view-3d').addEventListener('click',()=>setMode('3d'));$('#dimension-toggle').addEventListener('click',()=>setMode(state.mode==='2d'?'3d':'2d'));$('#explore-3d').addEventListener('click',()=>setMode('3d'));
 for(const key of ['spread','orbit','tilt'])$('#'+key).addEventListener('input',e=>{state[key]=Number(e.target.value);$('#'+key+'-value').value=state[key]+(key==='spread'?'':'°');fit();});
 function resetCamera(){state.zoom=1;state.orbit=-18;state.tilt=24;state.spread=75;for(const key of ['spread','orbit','tilt']){$('#'+key).value=state[key];$('#'+key+'-value').value=state[key]+(key==='spread'?'':'°');}fit();}
 $('#reset-camera').addEventListener('click',resetCamera);$('#fit-view').addEventListener('click',()=>{state.zoom=1;fit();});$('#zoom-in').addEventListener('click',()=>{state.zoom=Math.min(1.75,state.zoom+.1);fit();});$('#zoom-out').addEventListener('click',()=>{state.zoom=Math.max(.4,state.zoom-.1);fit();});
 $('#grid-toggle').addEventListener('click',()=>{state.grid=!state.grid;$('#viewport').classList.toggle('no-grid',!state.grid);$('#grid-toggle').setAttribute('aria-pressed',String(state.grid));$('#grid-toggle').classList.toggle('active',state.grid);});
 $('#motion-toggle').addEventListener('click',toggleMotion);$('#reduce-motion').addEventListener('change',e=>setReduced(e.target.checked));$('#reduce-toggle').addEventListener('click',()=>setReduced(!state.reduced));systemMotion.addEventListener('change',()=>setReduced(systemMotion.matches));
 $('#high-contrast').addEventListener('change',e=>{state.contrast=e.target.checked;document.body.classList.toggle('high-contrast',state.contrast);});
 function addLayer(){if(state.layers.length>=9){toast('This concept supports up to nine layers.');return;}const i=state.layers.length-5;const l={id:'note-'+(i+1),type:'note',name:'New note '+(i+1),x:40+i*28,y:560+i*145,z:60+i*20,width:360,height:125,opacity:96,radius:16,visible:true,locked:false};state.layers.push(l);state.selected=l.id;renderLayers();$('#layer-name').focus();$('#layer-name').select();toast('Note layer added. Give it a name.');}
 $('#add-layer').addEventListener('click',addLayer);$('#add-layer-bottom').addEventListener('click',addLayer);
 $('#about').addEventListener('click',()=>$('#about-dialog').showModal());document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
 $('#reset').addEventListener('click',()=>$('#reset-dialog').showModal());$('#confirm-reset').addEventListener('click',()=>{state.layers=structuredClone(defaults);state.selected='motion';state.playing=false;resetCamera();renderLayers();$('#reset-dialog').close();toast('Original workspace restored.');});
 function sceneData(){return {schemaVersion:'0.1',title:'Ourark World Studio — Layer Studio',renderer:'html-css3d-concept',makepadConnected:false,view:{mode:state.mode,spread:state.spread,orbit:state.orbit,tilt:state.tilt},preferences:{reducedMotion:state.reduced,highContrast:state.contrast},layers:structuredClone(state.layers)};}
 $('#export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(sceneData(),null,2)+'\n'],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ourark-world-studio-layers.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Scene exported with 2D positions and 3D depth.');});
 renderLayers();new ResizeObserver(fit).observe($('#viewport'));
 const context=document.modelContext;
 if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_dashboard_scene',title:'Read dashboard scene',description:'Read the current concept dashboard layers and view settings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>sceneData()});
 register({name:'set_dashboard_dimension',title:'Switch between 2D and 3D',description:'Switch the same dashboard layers to a flat 2D or spatial 3D view, preserving edits.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['2d','3d']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input!=='object'||!['2d','3d'].includes(input.mode))throw new Error('Choose 2d or 3d');return setMode(input.mode);}});
 addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
})();
